#include <string>
#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minCostPartition(std::string s, int k) {
        int n = s.length();
        std::vector<int> dp(n + 1, 1e9);
        dp[0] = 0;
        std::vector<int> pref1(n + 1, 0);
        for (int i = 0; i < n; ++i) pref1[i + 1] = pref1[i] + (s[i] == '1');
        for (int i = 1; i <= n; ++i) {
            for (int j = std::max(0, i - k); j < i; ++j) {
                int ones = pref1[i] - pref1[j];
                int zeros = (i - j) - ones;
                int cost = std::abs(ones - zeros);
                dp[i] = std::min(dp[i], dp[j] + cost);
            }
        }
        return dp[n];
    }
};

