class Solution {
    public int minCostPartition(String s, int k) {
        int n = s.length();
        int[] dp = new int[n + 1];
        Arrays.fill(dp, (int)1e9);
        dp[0] = 0;
        int[] pref1 = new int[n + 1];
        for (int i = 0; i < n; i++) pref1[i + 1] = pref1[i] + (s.charAt(i) == '1' ? 1 : 0);
        for (int i = 1; i <= n; i++) {
            for (int j = Math.max(0, i - k); j < i; j++) {
                int ones = pref1[i] - pref1[j];
                int zeros = (i - j) - ones;
                int cost = Math.abs(ones - zeros);
                dp[i] = Math.min(dp[i], dp[j] + cost);
            }
        }
        return dp[n];
    }
}

